// Length, required fields and limits come from registry/channels.json, injected at compile
// time as CHANNELS. A platform changing its limit is a registry edit, not a workflow edit.
const CHANNELS = $execution.customData?.get?.('channels') ?? JSON.parse($env.MOS_CHANNELS || '{}');
const b = $json.payload.brief;
const slot = $json.payload.slot || b.channels[0];
const spec = CHANNELS[slot.channel]?.formats?.[slot.format] || {};
return [{ json: { slot, spec, brief: b, research: $json.payload.research || null, profile: $json.payload.profile || {} } }];

