// Deterministic checks first — free, instant, and they catch most of what a reviewer would.
const out = $json.output || $json;
const profile = $('Resolve Channel Spec').first().json.profile || {};
const spec = $('Resolve Channel Spec').first().json.spec || {};
const lex = profile.message?.lexicon || {};
const text = [out.title, out.subtitle, out.body].filter(Boolean).join('\n');
const lower = text.toLowerCase();

const violations = [];
for (const term of (lex.banned || [])) if (lower.includes(term.toLowerCase())) violations.push({ severity: 'block', term });
for (const term of (lex.avoid || [])) if (lower.includes(term.toLowerCase())) violations.push({ severity: 'warn', term });

const words = text.split(/\s+/).filter(Boolean).length;
if (spec.min_words && words < spec.min_words) violations.push({ severity: 'warn', rule: 'below_min_words', words, min: spec.min_words });
if (spec.max_chars && text.length > spec.max_chars) violations.push({ severity: 'block', rule: 'over_max_chars', chars: text.length, max: spec.max_chars });
for (const field of (spec.requires || [])) if (!out[field]) violations.push({ severity: 'block', rule: 'missing_required_field', field });

return [{ json: { ...out, word_count: words, lint: { violations, blocked: violations.some(v => v.severity === 'block') } } }];
